def command(state, args):
    """Add an anime from an AniDB search."""
    if not args.query:
        return "No query provided."

    anime = state.anidb.search(args.query, limit=1)
    if not anime:
        return "No results found."

    anime = anime[0]

    if not anime.episodes:
        return "Anime has no episodes."

    if not anime.episodes[0].title:
        return "Anime episode has no title."

    state.add_anime(anime)

    return f"Added {anime.title}."

