def help(state, args):
    """Show help for a command."""
    if args.command:
        if args.command in state.commands:
            return state.commands[args.command].__doc__
        else:
            return "Command not found."
    else:
        return "No command provided."


def list(state, args):
    """List animes."""
    if args.anime:
        if args.anime in state.animes:
            anime = state.animes[args.anime]
            episodes = anime.episodes
            if not episodes:
                return "Anime has no episodes."
            if not episodes[0].title:
                return "Anime episode has no title."
            return "\n".join(
                f"{episode.number}. {episode.title}" for episode in episodes
            )
        else:
            return "Anime not found."
    else:
        return "\n".join(
            f"{anime.title} ({len(anime.episodes)})" for anime in state.animes
        )


def remove(state, args):
    """Remove an anime."""
    if args.anime:
        if args.anime in state.animes:
            state.remove_anime(args.anime)
            return f"Removed {args.anime}."
        else:
            return "Anime not found."
